// Cockpit ITSM public API - runtime core of the Node.js modules generated by CIPAT
// (Cockpit ITSM Public API Toolkit). Node.js 18+, ES module, no dependency
// (fetch, FormData and AbortSignal.timeout of Node.js).
//
// Maintained by hand, embedded in CIPAT and written next to each generated module:
// do not edit a copy, it is replaced when it differs from the generator's version.
//
// - OAuth 2.0 token (client_credentials, multipart/form-data, scope public-api),
//   renewed before expiry and once more on a 401 response;
// - HTTP: global fetch, replaceable (setFetch), e.g. by the fetch of undici with an
//   Agent accepting a self-signed certificate or going through a proxy;
// - paged lists: every page read, items merged and truncated to
//   totalNumberOfElements (fetchAllPages);
// - conversion helpers used by the generated module (missing or null = undefined).

/** Error answered by the API (non-2xx), network error or invalid response (statusCode 0). */
export class CockpitItsmError extends Error {
  /**
   * @param {number} statusCode HTTP status, 0 = no HTTP response or invalid JSON
   * @param {string} message
   * @param {string} [response] response body
   * @param {unknown} [cause]
   */
  constructor(statusCode, message, response = '', cause = undefined) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = 'CockpitItsmError';
    /** @type {number} */
    this.statusCode = statusCode;
    /** @type {string} */
    this.response = response ?? '';
  }
}

const DEFAULT_PAGE_SIZE = 500;
const TOKEN_MARGIN_MS = 60000;

/**
 * Message of an error answer: errorMessage (API), error_description / error (OAuth),
 * otherwise the start of the response.
 * @param {number} status
 * @param {string} text
 * @returns {CockpitItsmError}
 */
function httpError(status, text) {
  let msg = '';
  try {
    const v = text ? JSON.parse(text) : undefined;
    if (v && typeof v === 'object') {
      msg = [v.errorMessage, v.error_description, v.error].find((s) => typeof s === 'string' && s.trim() !== '') ?? '';
    }
  } catch {
    // not JSON
  }
  if (!msg) {
    msg = (text ?? '').trim();
    if (msg.length > 300) msg = msg.substring(0, 300) + '...';
  }
  return new CockpitItsmError(status, `Cockpit ITSM: HTTP error ${status} - ${msg}`, text);
}

/** Token, HTTP calls and paging. The generated class extends it. */
export class CockpitItsmCore {
  /**
   * @param {boolean} [saas] true: https://{tenant}.cockpit-itsm.com - false: https://{tenant}
   *   (an on-premise tenant given with its scheme, e.g. http://host:8080, is used as is)
   * @param {string} [tenant] tenant name (SaaS) or host name (on premise)
   * @param {string} [clientId]
   * @param {string} [clientSecret]
   */
  constructor(saas = true, tenant = '', clientId = '', clientSecret = '') {
    this._saas = saas;
    this._tenant = tenant ?? '';
    this._clientId = clientId ?? '';
    this._clientSecret = clientSecret ?? '';
    /** Page size of the paged lists (API maximum: 500). */
    this.pageSize = DEFAULT_PAGE_SIZE;
    /** Timeout of a request, in ms. */
    this.timeout = 60000;
    /** HTTP status of the last call. */
    this.lastStatus = 0;
    this._token = '';
    this._tokenExpiry = 0;
    /** @type {typeof fetch} */
    this._fetch = (input, init) => fetch(input, init);
  }

  // ---------------------------------------------------------------- settings (changing them discards the token)

  get saas() { return this._saas; }
  set saas(value) { this._saas = value; this.clearToken(); }
  get tenant() { return this._tenant; }
  set tenant(value) { this._tenant = value ?? ''; this.clearToken(); }
  get clientId() { return this._clientId; }
  set clientId(value) { this._clientId = value ?? ''; this.clearToken(); }
  get clientSecret() { return this._clientSecret; }
  set clientSecret(value) { this._clientSecret = value ?? ''; this.clearToken(); }

  /**
   * fetch used for every request (default: global fetch).
   * @param {typeof fetch} fn
   */
  setFetch(fn) {
    this._fetch = fn;
  }

  /**
   * @param {boolean} saas
   * @param {string} tenant
   * @returns {string}
   */
  static makeBaseUrl(saas, tenant) {
    const result = (tenant ?? '').trim().replace(/\/+$/, '');
    if (saas) return `https://${result}.cockpit-itsm.com`;
    return result.includes('://') ? result : `https://${result}`;
  }

  /** @returns {string} */
  get baseUrl() {
    return CockpitItsmCore.makeBaseUrl(this._saas, this._tenant);
  }

  // ---------------------------------------------------------------- token

  /** @returns {string} */
  get accessToken() { return this._token; }

  /** Expiry of the token (Date.now() value), 60 s before the server's one. */
  get tokenExpiry() { return this._tokenExpiry; }

  /** @returns {boolean} */
  isTokenValid() {
    return this._token !== '' && Date.now() < this._tokenExpiry;
  }

  clearToken() {
    this._token = '';
    this._tokenExpiry = 0;
  }

  /**
   * Token obtained elsewhere (shared between instances).
   * @param {string} token
   * @param {number} expiry Date.now() value
   */
  setToken(token, expiry) {
    this._token = token ?? '';
    this._tokenExpiry = expiry ?? 0;
  }

  /** POST /oauth2/token (multipart/form-data, client credentials, scope public-api). */
  async authenticate() {
    this.clearToken();
    if (!this._tenant || !this._clientId || !this._clientSecret) {
      throw new CockpitItsmError(0, 'Cockpit ITSM: tenant, clientId and clientSecret are required');
    }
    const form = new FormData();
    form.append('grant_type', 'client_credentials');
    form.append('client_id', this._clientId);
    form.append('client_secret', this._clientSecret);
    form.append('scope', 'public-api');
    const resp = await this._send('POST', this.baseUrl + '/oauth2/token', form, false);
    this.lastStatus = resp.status;
    if (resp.status !== 200) throw httpError(resp.status, resp.text);
    const obj = asObj(parse(resp.text));
    const token = obj ? toStr(obj.access_token) : undefined;
    if (!token) throw new CockpitItsmError(resp.status, 'Cockpit ITSM: no token in the response', resp.text);
    let ms = (toNum(obj?.expires_in) ?? 3600) * 1000;
    if (ms > 2 * TOKEN_MARGIN_MS) ms -= TOKEN_MARGIN_MS;
    this._token = token;
    this._tokenExpiry = Date.now() + ms;
  }

  /**
   * @param {string} method
   * @param {string} url
   * @param {string | FormData | undefined} body
   * @param {boolean} auth
   * @returns {Promise<{status: number, text: string}>}
   */
  async _send(method, url, body, auth) {
    /** @type {Record<string, string>} */
    const headers = { Accept: 'application/json' };
    if (auth) headers.Authorization = 'Bearer ' + this._token;
    /** @type {string | FormData | undefined} */
    let data = body;
    if (typeof body === 'string' || (body === undefined && ['POST', 'PUT', 'PATCH'].includes(method))) {
      headers['Content-Type'] = 'application/json; charset=utf-8';
      data = body ?? '';
    }
    let resp;
    try {
      resp = await this._fetch(url, { method, headers, body: data, signal: AbortSignal.timeout(this.timeout) });
    } catch (e) {
      const err = /** @type {any} */ (e);
      const detail = err?.cause?.message ?? err?.message ?? String(e);
      throw new CockpitItsmError(0, `Cockpit ITSM: ${err?.name ?? 'Error'} - ${detail} (${url})`, '', e);
    }
    return { status: resp.status, text: await resp.text() };
  }

  /**
   * Authenticated call; authenticates again once on 401; throws CockpitItsmError on a
   * non-2xx status. body: text sent as is, or object / array sent as JSON.
   * @param {string} method
   * @param {string} pathQuery e.g. "/api/end-users/12"
   * @param {string | object | undefined} [body]
   * @returns {Promise<string>} raw response
   */
  async call(method, pathQuery, body = undefined) {
    const data = body === undefined || body === null || typeof body === 'string' ? (body ?? undefined) : JSON.stringify(body);
    if (!this.isTokenValid()) await this.authenticate();
    let resp = await this._send(method, this.baseUrl + pathQuery, data, true);
    if (resp.status === 401) {
      await this.authenticate();
      resp = await this._send(method, this.baseUrl + pathQuery, data, true);
    }
    this.lastStatus = resp.status;
    if (resp.status < 200 || resp.status > 299) throw httpError(resp.status, resp.text);
    return resp.text;
  }

  /**
   * Parsed JSON response, undefined for an empty response.
   * @param {string} method
   * @param {string} pathQuery
   * @param {string | object | undefined} [body]
   * @returns {Promise<any>}
   */
  async callJson(method, pathQuery, body = undefined) {
    return parse(await this.call(method, pathQuery, body));
  }

  /**
   * Items ("content") of every page of a paged list, truncated to totalNumberOfElements.
   * @param {string} method
   * @param {string} pathQuery
   * @param {Record<string, any> | undefined} body
   * @param {string} pagePath dotted path of the {page, pageSize} object ("" = the body itself)
   * @returns {Promise<any[]>}
   */
  async fetchAllPages(method, pathQuery, body, pagePath) {
    /** @type {Record<string, any>} */
    const root = { ...(body ?? {}) };
    let pageObj = root;
    if (pagePath) {
      for (const name of pagePath.split('.')) {
        const child = pageObj[name] && typeof pageObj[name] === 'object' ? { ...pageObj[name] } : {};
        pageObj[name] = child;
        pageObj = child;
      }
    }
    /** @type {any[]} */
    const result = [];
    let page = 0;
    let totalPages = 1;
    let total = -1;
    do {
      pageObj.page = page;
      pageObj.pageSize = this.pageSize;
      const resp = asObj(await this.callJson(method, pathQuery, root));
      if (!resp) throw new CockpitItsmError(0, 'Cockpit ITSM: invalid paged response');
      if (page === 0) {
        totalPages = toNum(resp.totalNumberOfPages) ?? 1;
        total = toNum(resp.totalNumberOfElements) ?? -1;
      }
      const content = asArr(resp.content);
      if (!content || content.length === 0) break;
      result.push(...content);
      page++;
    } while (page < totalPages);
    if (total >= 0 && result.length > total) result.length = total;
    return result;
  }
}

// -------------------------------------------------------------------- URL

/**
 * @param {unknown} value
 * @returns {string}
 */
export function urlEncode(value) {
  return encodeURIComponent(String(value));
}

/**
 * Query parameter; undefined / null not sent, an array sent as repeated keys.
 * @param {Array<[string, string]>} query
 * @param {string} name
 * @param {unknown} value
 */
export function addQuery(query, name, value) {
  if (value === undefined || value === null) return;
  if (Array.isArray(value)) {
    for (const item of value) addQuery(query, name, item);
    return;
  }
  query.push([name, value instanceof Date ? formatDateTime(value) : String(value)]);
}

/**
 * "" or "?a=1&b=2"
 * @param {Array<[string, string]>} query
 * @returns {string}
 */
export function queryString(query) {
  if (query.length === 0) return '';
  return '?' + query.map(([n, v]) => encodeURIComponent(n) + '=' + encodeURIComponent(v)).join('&');
}

// -------------------------------------------------------------------- dates

/**
 * ISO 8601 date-time (Z, +hh:mm, +hhmm, no offset = UTC) -> Date; undefined if invalid.
 * @param {unknown} value
 * @returns {Date | undefined}
 */
export function parseDateTime(value) {
  if (typeof value !== 'string' || value.trim().length < 10) return undefined;
  let s = value.trim();
  if (s.length === 10) s += 'T00:00:00Z';
  else if (/[+-]\d{4}$/.test(s)) s = s.substring(0, s.length - 2) + ':' + s.substring(s.length - 2);
  else if (!/(Z|[+-]\d{2}:\d{2})$/i.test(s)) s += 'Z';
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? undefined : d;
}

/**
 * Date only: "yyyy-mm-dd" (time and offset ignored); undefined if invalid.
 * @param {unknown} value
 * @returns {string | undefined}
 */
export function parseDate(value) {
  if (typeof value !== 'string') return undefined;
  const s = value.trim().substring(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : undefined;
}

/**
 * Date -> UTC ISO 8601 with milliseconds ("2026-11-03T14:30:00.000Z").
 * @param {Date} value
 * @returns {string}
 */
export function formatDateTime(value) {
  return value.toISOString();
}

// -------------------------------------------------------------------- JSON: reading (undefined if missing, null or invalid)

/**
 * JSON text -> value; undefined for an empty text.
 * @param {string | undefined} text
 * @returns {any}
 */
export function parse(text) {
  if (text === undefined || text === null || text.trim() === '') return undefined;
  try {
    const v = JSON.parse(text);
    return v === null ? undefined : v;
  } catch (e) {
    throw new CockpitItsmError(0, 'Invalid JSON response: ' + /** @type {Error} */ (e).message, text, e);
  }
}

/**
 * @param {unknown} value
 * @returns {Record<string, any> | undefined}
 */
export function asObj(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value) ? /** @type {Record<string, any>} */ (value) : undefined;
}

/**
 * @param {unknown} value
 * @returns {any[] | undefined}
 */
export function asArr(value) {
  return Array.isArray(value) ? value : undefined;
}

/**
 * Text of a JSON string response ("abc" -> abc), other text unchanged.
 * @param {string | undefined} text
 * @returns {string | undefined}
 */
export function unquote(text) {
  if (text === undefined || text === null) return undefined;
  const s = text.trim();
  if (s.length >= 2 && s.startsWith('"') && s.endsWith('"')) {
    try {
      const v = JSON.parse(s);
      if (typeof v === 'string') return v;
    } catch {
      // not a JSON string
    }
  }
  return text;
}

/**
 * @param {unknown} v
 * @returns {string | undefined}
 */
export function toStr(v) {
  if (v === undefined || v === null) return undefined;
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
}

/**
 * @param {unknown} v
 * @returns {number | undefined}
 */
export function toNum(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : undefined;
  if (typeof v === 'string' && v.trim() !== '') {
    const n = Number(v.trim());
    return Number.isFinite(n) ? n : undefined;
  }
  if (typeof v === 'boolean') return v ? 1 : 0;
  return undefined;
}

/**
 * @param {unknown} v
 * @returns {boolean | undefined}
 */
export function toBool(v) {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  if (typeof v === 'number') return v !== 0;
  return undefined;
}

/**
 * @param {unknown} v
 * @returns {Date | undefined}
 */
export function toDateTime(v) {
  return parseDateTime(v);
}

/**
 * @param {unknown} v
 * @returns {string | undefined}
 */
export function toDate(v) {
  return parseDate(v);
}

/**
 * JSON text of a value (raw members).
 * @param {unknown} v
 * @returns {string | undefined}
 */
export function toRaw(v) {
  return v === undefined || v === null ? undefined : JSON.stringify(v);
}

/**
 * Converted items of a JSON array (null or invalid items dropped); undefined if the
 * array is missing.
 * @template T
 * @param {unknown} arr
 * @param {(v: any) => T | undefined} conv
 * @returns {T[] | undefined}
 */
export function listOf(arr, conv) {
  if (!Array.isArray(arr)) return undefined;
  /** @type {T[]} */
  const result = [];
  for (const v of arr) {
    const item = v === null || v === undefined ? undefined : conv(v);
    if (item !== undefined) result.push(item);
  }
  return result;
}

// -------------------------------------------------------------------- JSON: writing (undefined / null not written)

/**
 * JSON array of the converted items of a list (missing items kept as null).
 * @template T
 * @param {T[] | undefined} items
 * @param {(v: T) => any} [conv]
 * @returns {any[]}
 */
export function arrayOf(items, conv) {
  if (!items) return [];
  return items.map((v) => (v === undefined || v === null ? null : conv ? conv(v) : v));
}

/**
 * @param {Date | undefined} value
 * @returns {string | undefined}
 */
export function fromDateTime(value) {
  return value instanceof Date ? formatDateTime(value) : undefined;
}

/**
 * @param {Record<string, any>} obj
 * @param {string} name
 * @param {unknown} value
 */
export function put(obj, name, value) {
  if (value === undefined || value === null) return;
  obj[name] = value instanceof Date ? formatDateTime(value) : value;
}

/**
 * Raw member: JSON text inserted as a value.
 * @param {Record<string, any>} obj
 * @param {string} name
 * @param {string | undefined} text
 */
export function putRaw(obj, name, text) {
  if (text === undefined || text === null || text.trim() === '') return;
  obj[name] = JSON.parse(text);
}
